CREATE TABLE semio_animation_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_animation_timeline (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_animation_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), name TEXT);
CREATE TABLE semio_animation_channel (id INTEGER PRIMARY KEY, timeline_id INTEGER NOT NULL REFERENCES semio_animation_timeline(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), target_node TEXT NOT NULL, target_property TEXT NOT NULL CHECK (target_property IN ('translation','rotation','scale','weights','custom')), custom_property_name TEXT, interpolation TEXT NOT NULL CHECK (interpolation IN ('linear','step','cubic_spline')));
CREATE TABLE semio_animation_keyframe (id INTEGER PRIMARY KEY, channel_id INTEGER NOT NULL REFERENCES semio_animation_channel(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), time REAL, value_kind TEXT NOT NULL CHECK (value_kind IN ('scalar','vector3','quaternion','weights')), time_ieee754_bits INTEGER, time_numeric_class TEXT);
CREATE TABLE semio_animation_scalar (id INTEGER PRIMARY KEY REFERENCES semio_animation_keyframe(id), value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_animation_vector3 (id INTEGER PRIMARY KEY REFERENCES semio_animation_keyframe(id), x REAL, y REAL, z REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT);
CREATE TABLE semio_animation_quaternion (id INTEGER PRIMARY KEY REFERENCES semio_animation_keyframe(id), x REAL, y REAL, z REAL, w REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT, w_ieee754_bits INTEGER, w_numeric_class TEXT);
CREATE TABLE semio_animation_weight (id INTEGER PRIMARY KEY, keyframe_id INTEGER NOT NULL REFERENCES semio_animation_keyframe(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
